5	import AllocationChart from '@/components/charts/AllocationChart.vue'
6	import SkeletonCard from '@/components/ui/SkeletonCard.vue'
7	
8	const portfolio = usePortfolioStore()
9	
10	onMounted(() => portfolio.fetchPortfolio())
11	</script>
